@RestController
@RequestMapping("/api/users")
public class UserController {

    @PostMapping
    public ResponseEntity<User> createUser(@RequestBody User user) {
        // user object is already populated from JSON request body
        var saved = userService.save(user);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }
}

record User(String name, String email, int age) {}

// Client sends: POST /api/users with body {"name":"Alice","email":"alice@example.com","age":25}
// Spring deserializes JSON into User record automatically
// If Content-Type header is missing, you get 415 Unsupported Media Type

@Controller
@RequestMapping("/api/products")
public class ProductController {

    @GetMapping("/{id}")
    @ResponseBody // explicitly needed because this is @Controller, not @RestController
    public Product getProduct(@PathVariable Long id) {
        return productService.findById(id);
        // Spring serializes Product object to JSON automatically
    }
}

// Better: use @RestController so @ResponseBody is implicit
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping
    public List<Order> getAllOrders() {
        return orderService.findAll(); // no @ResponseBody needed, it's implicit
    }
}

record Product(Long id, String name, double price) {}
record Order(Long id, String customer, List<String> items) {}

@RestController
@RequestMapping("/api/users")
public class UserController {

    @GetMapping("/profile")
    public ResponseEntity<UserProfile> getProfile(
        @RequestHeader("Authorization") String authHeader,
        @RequestHeader(value = "X-Request-ID", required = false, defaultValue = "unknown") String requestId,
        @CookieValue(value = "session-id", required = false) String sessionId
    ) {
        var token = authHeader.replace("Bearer ", ""); // extract JWT token
        var profile = userService.getProfile(token);
        return ResponseEntity.ok(profile);
    }

    @GetMapping("/debug")
    public Map<String, String> debugHeaders(@RequestHeader Map<String, String> headers) {
        return headers; // returns all request headers as JSON
    }
}

record UserProfile(String username, String email) {}

@RestController
@RequestMapping("/api/products")
public class ProductController {

    // @RequestParam: extracts from query string
    @GetMapping
    public List<Product> search(
            @RequestParam String category,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {
        // Called via: GET /api/products?category=electronics&page=0&size=20
        return productService.findByCategory(category, page, size);
    }

    // @RequestBody: extracts from request body (JSON payload)
    @PostMapping
    public Product create(@RequestBody CreateProductRequest request) {
        // Called via: POST /api/products with JSON body:
        // {"name":"Laptop","price":999.99,"category":"electronics"}
        return productService.create(request);
    }
}

record CreateProductRequest(String name, double price, String category) {}

@RestController
@RequestMapping("/api/users")
public class UserController {

    @PostMapping
    public ResponseEntity<User> createUser(@Valid @RequestBody CreateUserRequest request) {
        var user = userService.create(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(user);
    }
}

record CreateUserRequest(
    @NotBlank(message = "Name is required") String name,
    @Email(message = "Invalid email format") String email,
    @Min(value = 18, message = "Must be at least 18") int age
) {}

// If client sends {"name":"","email":"bad-email","age":15}:
// Spring validates, finds 3 violations, throws MethodArgumentNotValidException
// Returns 400 with error details before createUser method runs

record User(Long id, String name, String email, int age) {}

@RestController
@RequestMapping("/api/users")
public class UserController {
    private final UserService userService;

    // Input DTO: only fields needed to create a user
    @PostMapping
    public UserResponse createUser(@RequestBody CreateUserRequest request) {
        var user = userService.create(request);
        return toResponse(user); // Convert entity to output DTO
    }

    // Output DTO: exclude sensitive fields, include computed fields
    @GetMapping("/{id}")
    public UserResponse getUser(@PathVariable Long id) {
        var user = userService.findById(id);
        return toResponse(user);
    }

    private UserResponse toResponse(User user) {
        return new UserResponse(user.getId(), user.getName(), user.getEmail());
    }
}

// Input DTO: what the client sends
record CreateUserRequest(String name, String email, String password) {}

// Output DTO: what the API returns (no password!)
record UserResponse(Long id, String name, String email) {}
